<template><main class="register-page"><div class="register-intro"><span class="eyebrow">CREATE ACCOUNT</span><h1>创建用户账号</h1><p>注册后进入用户中心，完成个人或企业认证。</p></div><el-form class="register-form" label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="form.username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item label="确认密码"><el-input v-model="form.confirmPassword" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item v-if="verification?.captchaEnabled" label="验证码"><el-input v-model="form.code" /><img v-if="captchaImage" :src="captchaImage" alt="验证码" /></el-form-item><p v-if="errorMessage" class="error" role="alert">{{ errorMessage }}</p><el-button type="primary" native-type="submit" :loading="loading" class="submit">注册</el-button><router-link to="/login" class="back">已有账号，返回登录</router-link></el-form></main></template>
<script setup lang="ts">import { computed, onMounted, reactive, ref } from 'vue'; import { identityAccessService } from '@/application/services'; const loading = ref(false); const errorMessage = ref(''); const verification = ref<Awaited<ReturnType<typeof identityAccessService.prepareLogin>>['verification']>(); const form = reactive({ username: '', password: '', confirmPassword: '', code: '' }); const captchaImage = computed(() => verification.value?.captchaEnabled ? `data:image/gif;base64,${verification.value.img}` : ''); async function prepare() { try { const result = await identityAccessService.prepareLogin(); verification.value = result.verification; } catch (error) { errorMessage.value = error instanceof Error ? error.message : '注册入口暂不可用'; } } async function submit() { if (form.password !== form.confirmPassword) { errorMessage.value = '两次输入的密码不一致'; return; } loading.value = true; errorMessage.value = ''; try { await identityAccessService.register({ ...form, ...(verification.value?.uuid ? { uuid: verification.value.uuid } : {}) }); window.location.href = `${import.meta.env.VITE_APP_CONTEXT_PATH}login`; } catch (error) { errorMessage.value = error instanceof Error ? error.message : '注册失败，请稍后重试'; } finally { loading.value = false; } } onMounted(prepare);</script>
<style scoped>.register-page { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 64px; max-width: 920px; margin: 0 auto; padding: 86px 28px; align-items: center; }.eyebrow { color: #0f766e; font-size: 12px; font-weight: 700; letter-spacing: .14em; }.register-intro h1 { margin: 12px 0; font-size: 42px; }.register-intro p { color: #64748b; line-height: 1.7; }.register-form { padding: 28px; border: 1px solid #dbe4ea; border-radius: 8px; background: #fff; }.register-form img { display: block; width: 120px; height: 38px; margin-top: 8px; object-fit: contain; }.submit { width: 100%; }.back { display: block; margin-top: 16px; color: #0f766e; font-size: 13px; text-align: center; text-decoration: none; }.error { color: #b42318; font-size: 13px; }@media (max-width: 700px) { .register-page { grid-template-columns: 1fr; gap: 28px; padding: 44px 18px; } }
</style>
